USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_GetPending @EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON; SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.TOTAL_ESTIMATED_AMOUNT,w.CURRENT_STAGE FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID JOIN dbo.CONCERN_DIVISION_OFFICIAL o ON o.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID AND o.EMPLOYEE_ID=@EmployeeId AND o.IS_ACTIVE=1 WHERE w.CURRENT_STAGE='CONCERN_DIVISION' AND w.COMPLETED_DATE IS NULL; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_VerifyComplete @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN DECLARE @next VARCHAR(40)=(SELECT r.DESTINATION_AFTER_CONCERN FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.COMPLETED_DATE IS NULL); EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_DIVISION','CONCERN_VERIFY_COMPLETE','CONCERN_OFFICIAL',@next,@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_ForwardToAuthority @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'CONCERN_DIVISION','CONCERN_FORWARD_TO_AUTHORITY','CONCERN_OFFICIAL','CONCERN_AUTHORITY',@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_Return @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'CONCERN_OFFICIAL','IN_WORKFLOW','CONCERN_RETURN','RETURNED','PROCUREMENT_OFFICER',@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ConcernDivision_NotRecommend @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'CONCERN_OFFICIAL','IN_WORKFLOW','CONCERN_NOT_RECOMMEND','NOT_RECOMMENDED','END',@Remarks,@BatchReferenceId; END;
GO

